#!/usr/bin/env python3
"""Generate docs/evidence/p54/RESULTS.md from the write-once results. `--check` verifies the doc is current."""
import json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, ROOT)
D = os.path.join(ROOT, "results/v2/p54-integration"); R = json.load(open(os.path.join(D, "result.json"))); M = json.load(open(os.path.join(D, "manifest.json")))
OUT = os.path.join(ROOT, "docs/evidence/p54/RESULTS.md")
c = lambda x: "%d/%d [%.2f, %.2f]" % (x["k"], x["n"], x["ci"][0], x["ci"][1])
def build():
    L = ["# P54 results — integration and assurance (CANDIDATE)", "", "Generated from `results/v2/p54-integration/result.json` (write-once). This phase adds **no new mechanism**: it audits, freezes, joins and re-checks the evidence of P39–P53. Nothing here is VERIFIED, and a PASS below means only that the named checks held on the candidate evidence in this repository.", "",
         "## ES-G1..ES-G16", "", "| gate | status | what it requires | failed checks | note |", "|---|---|---|---|---|"]
    for g in R["gates"]: L.append("| %s | **%s** | %s | %s | %s |" % (g["id"], g["status"], g["title"], ", ".join(g["failed"]) or "—", g["note"] or "—"))
    st = [g["status"] for g in R["gates"]]; L += ["", "%d PASS, %d FAIL, %d SKIP. FAIL entries are real findings about this repository and are not worked around." % (st.count("PASS"), st.count("FAIL"), st.count("SKIP")), "",
          "## P0–P38 prerequisites (P54-01) and the freeze (P54-02)", "", "%d of %d original task IDs have a command in `spec/acceptance.json`; the other **%d are BLOCKED** for new security claims. Mapped does not mean verified." % (R["audit"]["mapped"], R["audit"]["total"], R["audit"]["blocked"]), "", "| phase | mapped / total | status |", "|---|---|---|"]
    for p in R["audit"]["phases"]: L.append("| %s | %d / %d | %s |" % (p["phase"], p["mapped"], p["total"], p["status"]))
    L += ["", "`results/v2/p54-integration/freeze.json` holds the digest of the 710 task-ID list and a sha256 of every file under `results/v2/` (except P54's own) as of the start of P54. `python3 scripts/p54_run.py --check` fails if any of them changes.", "",
          "## Paired headline per module (recorded results, Wilson 95%)", "", "Each pair is the module's own: attacks prevented / attack runs, and benign tasks completed / benign runs (for the three detection/coverage modules: detected / true positives, and correctly passed / benign). Counts are scenarios, not independent trials; every suite was written by the author of the module and its baselines.", "",
          "| module | family | headline system | attacks prevented [CI] | benign completed [CI] | notes |", "|---|---|---|---|---|---|"]
    for r in R["table"]: L.append("| %s %s | %s | %s | %s | %s | %s |" % (r["module"], r["name"], r["family"], r["system"], c(r["attack_prevented"]), c(r["benign_completed"]), "; ".join(r["notes"]) or "—"))
    L += ["", "| family | modules | attacks prevented (pooled, descriptive) | benign completed (pooled, descriptive) |", "|---|---|---|---|"]
    for k, f in R["families"].items(): L.append("| %s | %s | %d/%d [%.2f, %.2f] | %d/%d [%.2f, %.2f] |" % (k, ", ".join(f["modules"]), f["attack_k"], f["attack_n"], f["attack_ci"][0], f["attack_ci"][1], f["benign_k"], f["benign_n"], f["benign_ci"][0], f["benign_ci"][1]))
    L += ["", "Pooling across modules mixes different scenario sets and is shown only so the families can be compared at a glance.", "", "## Negative findings (P54-14)", "", "| module | finding | source |", "|---|---|---|"] + ["| %s | %s | `%s` |" % (n["module"], n["finding"], n["source"]) for n in R["negative_findings"]]
    L += ["", "## One receipt service, oracle independence, authority sites (P54-05, P54-09)", "", "All 15 modules get a receipt from one `ReceiptService` (one issuer, role `receipts`, kind ATTESTATION on the shared `HorizonPolicy`); `INTACT` means the recorded result and the oracle and system files still hash as when the receipt was issued. It is evidence integrity only.", "", "| module | receipt | oracle files reach system-under-test code (static, transitive intra-package imports) |", "|---|---|---|"]
    ind = {i["module"]: i for i in R["review"]["independence"]}
    for v in R["receipts"]: L.append("| %s | %s | %s |" % (v["module"], v["verdict"], "no" if ind[v["module"]]["independent"] else "**yes**: " + "; ".join("%s → %s" % (o["oracle"], ", ".join(o["reaches_system"])) for o in ind[v["module"]]["oracle_files"] if o["reaches_system"])))
    A = R["review"]["authority"]; L += ["", "Signers/authorities created in `horizon/` outside the shared authority: %d sites. By role: %s. **Not fixtures or evidence services (duplicate authority until proven otherwise): %s.**" % (A["sites"], "; ".join("%s: %d files" % (k, len(v)) for k, v in A["by_role"].items()), ", ".join("`%s`" % f for f in A["other_files"])), "",
          "## Protocol equivalence (P54-06)", "", "%d generated workflows over %s (shared decision function; verdict may not depend on protocol). Discrepancies: %d, of which unexpected (not in `results/v2/p14-parity/expected_discrepancies.json`): **%d**. The expected one is `%s`: UTCP serializes the body as JSON, so the same target and verdict carry different bytes. Metamorphic URL-spelling violations: %d. Alias traps allowed: %d of %d. Non-equivalent fixtures all flagged: %s. Carrier codec round trip (P50): %s. Browser adapter: %s. Native adapters: %s." % (
              R["protocols"]["parity"]["workflows"], ", ".join(R["protocols"]["parity"]["paths"]), R["protocols"]["discrepancy_count"], len(R["protocols"]["unexpected_discrepancies"]), ", ".join(R["protocols"]["expected"]), len(R["protocols"]["parity"]["metamorphic_discrepancies"]), sum(t["allowed"] for t in R["protocols"]["parity"]["traps"]), len(R["protocols"]["parity"]["traps"]),
              R["protocols"]["non_equivalent_fixtures_flagged"], ", ".join(k for k, v in R["protocols"]["carrier_roundtrip"].items() if v), "recorded in %s, not re-run here" % R["protocols"]["browser"]["source"], R["protocols"]["native_adapters"]),
          "", "## Concurrency, replay and retry (P54-11)", "", "| check | ok | detail |", "|---|---|---|"] + ["| %s | %s | %s |" % (x["name"], x["ok"], json.dumps(x["detail"], sort_keys=True)) for x in R["statemachine"]]
    T = R["tamper"]; E = T["evaluator"]; L += ["", "## Lost coverage and tampered evaluator records (P54-10)", "", "* P49 evaluator, every scenario where the run really violated policy and the stated assumptions hold: **%d violating runs, %d false PASS**; verdicts seen: %s." % (E["violating_runs"], E["false_pass"], ", ".join(E["verdicts"])), "* Outside P49's assumptions: %s. %s." % (", ".join("%s → %s" % (x["scenario"], x["verdict"]) for x in E["outside_assumptions"]), E["note"]),
          "* Control: the four weaker graders on the same runs give false PASS counts %s." % ", ".join("%s %d/%d" % (k, v["false_pass"], v["violating_runs"]) for k, v in T["evaluator_baselines"].items()), "* Receipt verdicts under edited evidence: %s." % ", ".join("%s → %s" % (k, v["verdict"]) for k, v in T["receipts"].items()),
          "* P53 with the revocation feed offline and the handle revoked: prohibited effect %s, flagged UNKNOWN %s; benign migration with the feed offline completed: %s (it rolls back: safe, but not available)." % (T["coverage_loss"]["p53_revoked_and_feed_offline"]["prohibited_effect"], T["coverage_loss"]["p53_revoked_and_feed_offline"]["unknown"], T["coverage_loss"]["p53_benign_and_feed_offline"]["completed"]),
          "* Recorded, not re-run: P42 detected %d of %d injected regressions with healthy-control false alarm %s; P52 telemetry-offline: attack violated %s, benign completed %s." % (T["coverage_loss"]["p42_recorded"]["regressions_detected"], T["coverage_loss"]["p42_recorded"]["regressions"], T["coverage_loss"]["p42_recorded"]["healthy_false_alarm"], T["coverage_loss"]["p52_recorded"]["attack_violated"], T["coverage_loss"]["p52_recorded"]["benign_completed"]),
          "", "## Reproduction on this machine (P54-07, P54-08, P54-13)", "", "Same machine, same author. **Not** the independent clean-checkout review of P54-16.", "", "| module | level | ok | what ran |", "|---|---|---|---|"]
    for x in R["reproduction"]: L.append("| %s | %s | %s | %s |" % (x["module"], x["level"], x["ok"], x.get("note", "fresh run's paired headline equals the recorded one") if x["level"] != "module-tests" else x["output"]) if x["level"] == "rerun" else "| %s | %s + module tests | %s | `--check`: %s; tests: %s |" % (x["module"], x["level"], x["ok"], x["output"], x["module_tests"]["output"]))
    r = R["review"]; L += ["", "## Static review (P54-12)", "", "* Calls to eval/exec/compile/subprocess/os.system/pickle/shell=True in `horizon/`: **%d**, in %d files (the process-based sandboxes, mock receivers and the code-mode executor spawn local helper processes by design; `horizon/downgrade/gateway.py` uses exec/compile for its rule engine). Listed in `result.json`." % (len(r["dangerous_calls"]), len({d["file"] for d in r["dangerous_calls"]})),
          "* Hostnames appearing as string literals in library code that are not reserved/synthetic: %s (both are documentation or schema identifiers, not fetched; `scripts/p30_no_external.py` is the enforcing scan)." % (", ".join("`%s` (%s)" % (h, ", ".join(f)) for h, f in r["non_reserved_hosts"].items()) or "none"), "* Secret scan, no-external-contact scan, inventory and README freeze are checked by CI, not re-derived here.", ""]
    return "\n".join(L)
def main():
    t = build()
    if "--check" in sys.argv: ok = os.path.exists(OUT) and open(OUT).read() == t; print("up to date" if ok else "STALE"); sys.exit(0 if ok else 1)
    os.makedirs(os.path.dirname(OUT), exist_ok=True); open(OUT, "w").write(t); print("written", len(t))
main()
